  --surface:      #1a1d27;
  --surface-2:    #22263a;
  --border:       #2e3250;
  --text:         #e2e4f0;
  --text-muted:   #7c82a0;
  --accent:       #6c7dff;
  --accent-hover: #8a98ff;
  --danger:       #e05263;
  --danger-hover: #f06475;
  --danger-dim:   rgba(224, 82, 99, 0.15);
  --focus-ring:   0 0 0 3px rgba(108, 125, 255, 0.55);
  --radius-sm:    6px;
  --radius-md:    12px;
  --radius-lg:    18px;
  --shadow-dialog: 0 24px 64px rgba(0, 0, 0, 0.7);
  --transition:   150ms ease;
}

html { color-scheme: dark; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.5;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

/* ─── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -9999px; left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1.25rem;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  white-space: nowrap;
}
.skip-link:focus { top: 0; }

/* ─── Layout ────────────────────────────────────────────────────── */
header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 2rem;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}
header .logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  text-decoration: none;
  color: var(--text);
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}
header .logo svg { flex-shrink: 0; }
header .breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  margin-left: auto;
  font-size: 0.875rem;
  color: var(--text-muted);
  list-style: none;
}
header .breadcrumb li + li::before {
  content: "/";
  margin-right: 0.375rem;
  opacity: 0.5;
}
header .breadcrumb a {
  color: var(--text-muted);
  text-decoration: none;
}
header .breadcrumb a:hover,
header .breadcrumb a:focus-visible { color: var(--text); text-decoration: underline; }
header .breadcrumb [aria-current="page"] { color: var(--text); }

main {
  flex: 1;
  padding: 2.5rem 2rem;
  max-width: 900px;
  width: 100%;
  margin: 0 auto;
}

/* ─── Image preview card ─────────────────────────────────────────── */
.image-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: 0 4px 24px rgba(0,0,0,0.4);
}

.image-card__figure {
  position: relative;
  background: #0a0c12;
  margin: 0;
}
.image-card__figure img {
  display: block;
  width: 100%;
  height: clamp(260px, 45vw, 500px);
  object-fit: cover;
  object-position: center;
}
.image-card__badge {
  position: absolute;
  top: 1rem; right: 1rem;
  background: rgba(0,0,0,0.65);
  backdrop-filter: blur(6px);
  color: var(--text-muted);
  font-size: 0.75rem;
  padding: 0.25rem 0.625rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  letter-spacing: 0.02em;
}

.image-card__body {
  padding: 1.5rem 1.75rem;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 1.25rem;
}

.image-card__meta { flex: 1; min-width: 0; }
.image-card__title {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-bottom: 0.25rem;
}
.image-card__subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.image-card__subtitle span {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.image-card__actions {
  display: flex;
  gap: 0.625rem;
  align-items: center;
  flex-shrink: 0;
}

/* ─── Buttons ────────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  text-decoration: none;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
  white-space: nowrap;
}
.btn:focus-visible { outline: none; box-shadow: var(--focus-ring); }

.btn--secondary {
  background: var(--surface-2);
  border-color: var(--border);
  color: var(--text);
}
.btn--secondary:hover { background: #2a2f4a; border-color: #3a4060; }

.btn--danger {
  background: var(--danger-dim);
  border-color: var(--danger);
  color: var(--danger);
}
.btn--danger:hover { background: rgba(224, 82, 99, 0.28); color: var(--danger-hover); }

/* ─── Dialog backdrop & element ────────────────────────────────── */
dialog {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-dialog);
  color: var(--text);
  max-width: min(440px, calc(100vw - 2rem));
  width: 100%;
  padding: 0;
  /* start hidden — browser default for <dialog>; stated explicitly for clarity */
}
dialog::backdrop {
  background: rgba(0, 0, 0, 0.72);
  backdrop-filter: blur(4px);
}

/* ─── Dialog internals ─────────────────────────────────────────── */
.dialog__icon-wrap {
  display: flex;
  justify-content: center;
  padding-top: 2rem;
}
.dialog__icon {
  width: 52px; height: 52px;
  border-radius: 50%;
  background: var(--danger-dim);
  border: 1px solid var(--danger);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--danger);
}

.dialog__header {
  padding: 1rem 1.75rem 0;
  text-align: center;
}
.dialog__title {
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.dialog__body {
  padding: 0.625rem 1.75rem 1.5rem;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.9375rem;
  line-height: 1.6;
}

.dialog__filename {
  display: inline-block;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0.125rem 0.5rem;
  font-family: ui-monospace, "Cascadia Code", "SF Mono", Consolas, monospace;
  font-size: 0.8125rem;
  color: var(--text);
  margin: 0.25rem 0;
}

.dialog__footer {
  display: flex;
  gap: 0.75rem;
  padding: 0 1.75rem 1.75rem;
  justify-content: center;
}
.dialog__footer .btn { flex: 1; justify-content: center; }

.btn--danger-solid {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.btn--danger-solid:hover { background: var(--danger-hover); border-color: var(--danger-hover); }

/* ─── Dialog open animation ─────────────────────────────────────── */
@media (prefers-reduced-motion: no-preference) {
  dialog[open] {
    animation: dialog-pop 220ms cubic-bezier(0.34, 1.36, 0.64, 1) forwards;
  }
  @keyframes dialog-pop {
    from { opacity: 0; transform: scale(0.94) translateY(8px); }
    to   { opacity: 1; transform: scale(1) translateY(0); }
  }
}

/* ─── Focus visible ─────────────────────────────────────────────── */
*:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
a:focus-visible  { outline: 2px solid var(--accent); outline-offset: 2px; }

/* ─── Footer ────────────────────────────────────────────────────── */
footer {
  padding: 1.25rem 2rem;
  border-top: 1px solid var(--border);
  text-align: center;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* ─── Reflow (320 px) ───────────────────────────────────────────── */
@media (max-width: 480px) {
  header { padding: 0.875rem 1rem; }
  header .breadcrumb { display: none; }
  main { padding: 1.5rem 1rem; }
  .image-card__body { flex-direction: column; }
  .image-card__actions { width: 100%; }
  .image-card__actions .btn { flex: 1; justify-content: center; }
  .dialog__footer { flex-direction: column-reverse; }
}
